import marshmallow as ma
from marshmallow import Schema, fields
from enum import Enum
import pytest

class MyEnum(Enum):
    A = "a"
    NONE = None

class S(Schema):
    sentinel = fields.Enum(MyEnum, by_value=True)

def test_enum_none_value_deserialization():
    data = {"sentinel": None}
    result = S().load(data)
    assert result["sentinel"] == MyEnum.NONE
